    args.to,
    args.subject,
    args.body,
    {
      cc: args.cc,
      bcc: args.bcc,
      html: args.html,
      replyTo: args['reply-to']
    }
  );

  // Send email
  const result = await gmail.users.messages.send({
    userId: 'me',
    requestBody: {
      raw: encodedMessage
    }
